-- 003_declined (decision 8, 12 to 14; v3 spec §1.2, §2.1): the one new stored status, `declined`, and
-- what the customer said when declining. SQLite can't alter a CHECK, so `quotes` is rebuilt with
-- SQLite's 12-step recipe: the runner has foreign_keys OFF and runs foreign_key_check afterwards.
-- Every column of `quotes` at 002 is copied, including 002_freight_recovery's four freight columns.
-- declined_at: when the customer declined. decline_reason: one of the five reasons, or NULL (Decline
-- works with no reason). decline_note: the "Other" text, plain, at most 250 characters, rep-only.
CREATE TABLE quotes_new(id TEXT PRIMARY KEY,quote_number TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL REFERENCES customers(id),contact_id TEXT REFERENCES contacts(id),rep_id TEXT NOT NULL REFERENCES reps(id),status TEXT NOT NULL CHECK(status IN ('ready_for_review','sent','accepted','changes_requested','expired','declined')),revision INTEGER NOT NULL DEFAULT 0,conversation_id TEXT REFERENCES conversations(id),request_text TEXT,requested_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sent_at TEXT,responded_at TEXT,fulfillment TEXT NOT NULL CHECK(fulfillment IN ('will_call','delivery')),branch_id TEXT NOT NULL REFERENCES branches(id),requested_date TEXT,fulfillment_time TEXT,ship_to_address TEXT,ship_to_lat REAL,ship_to_lng REAL,freight_override REAL,freight_override_reason TEXT,valid_days INTEGER NOT NULL DEFAULT 14 CHECK(valid_days IN (7,14,30)),valid_until TEXT,expires_on TEXT CHECK(expires_on IS NULL OR expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),customer_po TEXT,customer_note TEXT,change_request_note TEXT,unread_for_rep INTEGER NOT NULL DEFAULT 0,unread_for_customer INTEGER NOT NULL DEFAULT 0,is_sample INTEGER NOT NULL DEFAULT 0,duplicated_from TEXT REFERENCES quotes(id),freight_rate_bp INTEGER,freight_ramp_step INTEGER,freight_ramp_steps INTEGER,modelled_freight_cents INTEGER,declined_at TEXT,decline_reason TEXT CHECK(decline_reason IN ('price_too_high','found_other_source','need_sooner','wrong_items','other')),decline_note TEXT CHECK(decline_note IS NULL OR length(decline_note)<=250));
INSERT INTO quotes_new(id,quote_number,customer_id,contact_id,rep_id,status,revision,conversation_id,request_text,requested_at,created_at,updated_at,sent_at,responded_at,fulfillment,branch_id,requested_date,fulfillment_time,ship_to_address,ship_to_lat,ship_to_lng,freight_override,freight_override_reason,valid_days,valid_until,expires_on,customer_po,customer_note,change_request_note,unread_for_rep,unread_for_customer,is_sample,duplicated_from,freight_rate_bp,freight_ramp_step,freight_ramp_steps,modelled_freight_cents)
  SELECT id,quote_number,customer_id,contact_id,rep_id,status,revision,conversation_id,request_text,requested_at,created_at,updated_at,sent_at,responded_at,fulfillment,branch_id,requested_date,fulfillment_time,ship_to_address,ship_to_lat,ship_to_lng,freight_override,freight_override_reason,valid_days,valid_until,expires_on,customer_po,customer_note,change_request_note,unread_for_rep,unread_for_customer,is_sample,duplicated_from,freight_rate_bp,freight_ramp_step,freight_ramp_steps,modelled_freight_cents FROM quotes;
DROP TABLE quotes;
ALTER TABLE quotes_new RENAME TO quotes;
CREATE INDEX quotes_customer ON quotes(customer_id,requested_at);
